def validate_generated_code():
    """Load the PTX module and verify both entry points resolve correctly."""
    module = _get_module()
    fn_reduce = module.function("layernorm_reduce_kernel")
    fn_norm = module.function("layernorm_normalize_kernel")
    assert fn_reduce is not None, "layernorm_reduce_kernel entry not found in PTX module"
    assert fn_norm is not None, "layernorm_normalize_kernel entry not found in PTX module"
