class ModelNew(nn.Module):
    """
    LayerNorm implemented with hand-authored PTX kernels executed through
    cutegen.ptx_runtime.PtxModule. The normalization is split into two
    cooperating kernel launches (partial reduction + finalize/normalize)
    so that each row of the input is processed by multiple CTAs instead of
    a single CTA per row. This increases the total number of CUDA blocks
    launched (grid.x * grid.y) so the GPU's streaming multiprocessors are
    much better utilized, instead of only launching as many blocks as
    there are outer rows (N), which previously left most SMs idle.
    """
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))
        self._module = None
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self._module is None:
            self._module = _get_module()
        assert x.is_cuda, "x must be a CUDA tensor"
        # Avoid launching redundant elementwise cast/copy kernels (e.g. the
        # cudaMemcpy-style at::vectorized_elementwise_kernel used by .to()/
        # .contiguous()) when the tensors are already in the required
        # float32, contiguous, same-device layout that the PTX kernels need.
        if x.dtype == torch.float32 and x.is_contiguous():
            x_c = x
        else:
            x_c = x.contiguous().to(torch.float32)
        if (self.weight.dtype == torch.float32 and self.weight.is_contiguous()
                and self.weight.device == x_c.device):
            w_c = self.weight
        else:
            w_c = self.weight.contiguous().to(device=x_c.device, dtype=torch.float32)
        if (self.bias.dtype == torch.float32 and self.bias.is_contiguous()
                and self.bias.device == x_c.device):
            b_c = self.bias
        else:
            b_c = self.bias.contiguous().to(device=x_c.device, dtype=torch.float32)
        M = w_c.numel()
        assert M > 0, "normalized_shape must have non-zero numel"
        assert x_c.numel() % M == 0, "x numel must be divisible by normalized_shape numel"
        N = x_c.numel() // M
        y = torch.empty_like(x_c)
        # Split each row's reduction/normalization work across multiple CTAs
        # so that the total number of launched blocks (N * S) approaches
        # the number of SMs on the target GPU, instead of just N blocks.
        Nvec4 = M // 4
        # The reduction/normalize kernels are memory-bound (see profiler:
        # ~91% DRAM throughput but only ~33% achieved occupancy and a
        # tool warning that the grid was sized to exactly one block per
        # SM). Using a smaller CTA size together with a higher
        # blocks-per-SM launch target lets the scheduler keep several
